[a, Rm,d2R0_0,d4R0_0, ~,d2Z0_0,d4Z0_0, kappam,d2e_0,d4e_0, dS2_0,d3S2_0, dA2_0,d3A2_0, dS3_0,d3S3_0, dA3_0] = amps{:};

