    K1 = (1/2).*Rm.^(-1).*kappam.^(-1).*(1+kappam.^2).*mu0.^(-1).*rho1.*(1+(1/4).*Rm.^(-2).*rho1.^2.*(3+(-2).*(1+kappam.^2).^(-1)+Rm.^2.*kappam.^(-1).*(1+(-6).*(1+kappam.^2).^(-1)).*d2e_0+4.*Rm.^2.*(3+14.*(1+kappam.^2).^(-1)).*dA2_0.^2+Rm.*kappam.^(-1).*d2Z0_0.*(Rm.*kappam.^(-1).*(1+2.*(1+kappam.^2).^(-1)).*d2Z0_0+8.*Rm.*(1+(-4).*(1+kappam.^2).^(-1)).*dA2_0)+Rm.*d2R0_0.*(1+(-2).*(1+kappam.^2).^(-1)+Rm.*(3+(-2).*(1+kappam.^2).^(-1)).*d2R0_0+(-16).*Rm.*(1+kappam.^2).^(-1).*dS2_0)+4.*Rm.*dS2_0.*(1+(-2).*(1+kappam.^2).^(-1)+5.*Rm.*(1+2.*(1+kappam.^2).^(-1)).*dS2_0)+8.*a.^(-1).*Rm.^2.*dS3_0)+(1/24).*Rm.^(-4).*rho1.^4.*(3.*(5+(-4).*(1+kappam.^2).^(-1))+3.*Rm.^4.*kappam.^(-2).*(1+12.*(1+kappam.^2).^(-1)).*d2e_0.^2+(-12).*Rm.^4.*kappam.^(-1).*(1+kappam.^2).^(-1).*d2e_0.*d2R0_0.^2+3.*Rm.^4.*(5+(-4).*(1+kappam.^2).^(-1)).*d2R0_0.^4+(-12).*Rm.^4.*kappam.^(-3).*(1+5.*(1+kappam.^2).^(-1)).*d2e_0.*d2Z0_0.^2+18.*Rm.^4.*kappam.^(-2).*d2R0_0.^2.*d2Z0_0.^2+3.*Rm.^4.*kappam.^(-4).*(1+4.*(1+kappam.^2).^(-1)).*d2Z0_0.^4+(-4).*Rm.^4.*kappam.^(-1).*(1+kappam.^2).^(-1).*d4e_0+(-24).*Rm.^4.*kappam.^(-2).*(1+(-20).*(1+kappam.^2).^(-1)).*d2e_0.*d2Z0_0.*dA2_0+144.*Rm.^4.*kappam.^(-1).*(1+(-1).*(1+kappam.^2).^(-1)).*d2R0_0.^2.*d2Z0_0.*dA2_0+(-240).*Rm.^4.*kappam.^(-3).*(1+kappam.^2).^(-1).*d2Z0_0.^3.*dA2_0+2.*Rm.^3.*kappam.^(-1).*d4Z0_0.*(Rm.*kappam.^(-1).*(1+2.*(1+kappam.^2).^(-1)).*d2Z0_0+4.*Rm.*(1+(-4).*(1+kappam.^2).^(-1)).*dA2_0)+6.*Rm.^3.*d2R0_0.^3.*(1+(-1).*(1+kappam.^2).^(-1)+(-8).*Rm.*(1+kappam.^2).^(-1).*dS2_0)+2.*Rm.^3.*d4R0_0.*(1+(-1).*(1+kappam.^2).^(-1)+Rm.*(3+(-2).*(1+kappam.^2).^(-1)).*d2R0_0+(-8).*Rm.*(1+kappam.^2).^(-1).*dS2_0)+6.*Rm.^3.*kappam.^(-2).*d2R0_0.*d2Z0_0.^2.*(1+(-1).*(1+kappam.^2).^(-1)+(-24).*Rm.*(1+(1+kappam.^2).^(-1)).*dS2_0)+6.*Rm.^3.*kappam.^(-1).*d2e_0.*d2R0_0.*((1+kappam.^2).^(-1)+8.*Rm.*(1+3.*(1+kappam.^2).^(-1)).*dS2_0)+48.*Rm.^2.*kappam.^(-1).*d2R0_0.*d2Z0_0.*((-3).*a.^(-1).*Rm.^2.*(1+(-2).*(1+kappam.^2).^(-1)).*dA3_0+Rm.*dA2_0.*(1+(-6).*Rm.*(1+(-4).*(1+kappam.^2).^(-1)).*dS2_0))+(-48).*a.^(-1).*Rm.^2.*dA3_0.*((-8).*a.^(-1).*Rm.^2.*dA3_0+Rm.*dA2_0.*(1+8.*(1+kappam.^2).^(-1)+(-12).*Rm.*(1+6.*(1+kappam.^2).^(-1)).*dS2_0))+(-24).*Rm.^2.*dA2_0.^2.*(1+(-6).*(1+kappam.^2).^(-1)+(-2).*Rm.^2.*(3+104.*(1+kappam.^2).^(-1)).*dA2_0.^2+(-2).*Rm.*dS2_0.*(1+(-2).*(1+kappam.^2).^(-1)+2.*Rm.*(11+72.*(1+kappam.^2).^(-1)).*dS2_0))+12.*Rm.*dS2_0.*(3+(-4).*(1+kappam.^2).^(-1)+2.*Rm.*dS2_0.*(1+2.*(1+kappam.^2).^(-1)+2.*Rm.*dS2_0.*(1+(-2).*(1+kappam.^2).^(-1)+Rm.*(19+40.*(1+kappam.^2).^(-1)).*dS2_0)))+(-24).*a.^(-1).*Rm.^2.*dS3_0.*(1+(-2).*(1+kappam.^2).^(-1)+(-4).*Rm.^2.*(7+(-6).*(1+kappam.^2).^(-1)).*dA2_0.^2+2.*Rm.*dS2_0.*(3.*(1+2.*(1+kappam.^2).^(-1))+(-2).*Rm.*(17+22.*(1+kappam.^2).^(-1)).*dS2_0)+(-24).*a.^(-1).*Rm.^2.*dS3_0)+6.*Rm.^2.*kappam.^(-1).*d2e_0.*(1+(-2).*(1+kappam.^2).^(-1)+(-4).*Rm.^2.*(1+32.*(1+kappam.^2).^(-1)).*dA2_0.^2+4.*Rm.*dS2_0.*(1+(-3).*Rm.*(1+8.*(1+kappam.^2).^(-1)).*dS2_0)+(-8).*a.^(-1).*Rm.^2.*dS3_0)+3.*Rm.^2.*kappam.^(-2).*d2Z0_0.^2.*(1+16.*Rm.^2.*(2+31.*(1+kappam.^2).^(-1)).*dA2_0.^2+(-4).*Rm.*dS2_0.*(3+(-4).*Rm.*(8+13.*(1+kappam.^2).^(-1)).*dS2_0)+8.*a.^(-1).*Rm.^2.*(5+(-2).*(1+kappam.^2).^(-1)).*dS3_0)+3.*Rm.^2.*d2R0_0.^2.*(1+16.*Rm.^2.*(3+(-1).*(1+kappam.^2).^(-1)).*dA2_0.^2+4.*Rm.*dS2_0.*(1+4.*Rm.*(3+5.*(1+kappam.^2).^(-1)).*dS2_0)+8.*a.^(-1).*Rm.^2.*(3+2.*(1+kappam.^2).^(-1)).*dS3_0)+32.*Rm.^4.*(1+6.*(1+kappam.^2).^(-1)).*dA2_0.*d3A2_0+8.*Rm.*kappam.^(-1).*d2Z0_0.*((-6).*a.^(-1).*Rm.^2.*dA3_0.*(1+(-2).*(1+kappam.^2).^(-1)+4.*Rm.*(1+4.*(1+kappam.^2).^(-1)).*dS2_0)+3.*Rm.*dA2_0.*(1+(-2).*(1+kappam.^2).^(-1)+4.*Rm.^2.*(1+(-48).*(1+kappam.^2).^(-1)).*dA2_0.^2+2.*Rm.*dS2_0.*((1+kappam.^2).^(-1)+(-2).*Rm.*(1+44.*(1+kappam.^2).^(-1)).*dS2_0))+12.*a.^(-1).*Rm.^3.*(3+(-2).*(1+kappam.^2).^(-1)).*dA2_0.*dS3_0+Rm.^3.*(1+(-6).*(1+kappam.^2).^(-1)).*d3A2_0)+(-8).*Rm.^3.*((1+kappam.^2).^(-1)+(-8).*Rm.*(1+2.*(1+kappam.^2).^(-1)).*dS2_0).*d3S2_0+(-2).*Rm.*d2R0_0.*(3.*(2+(-1).*(1+kappam.^2).^(-1))+12.*Rm.^2.*dS2_0.^2.*(3.*(1+kappam.^2).^(-1)+4.*Rm.*(5+12.*(1+kappam.^2).^(-1)).*dS2_0)+12.*Rm.^2.*dA2_0.^2.*(5.*(1+kappam.^2).^(-1)+4.*Rm.*(3+16.*(1+kappam.^2).^(-1)).*dS2_0)+(-24).*((-8).*a.^(-1).*Rm.^3.*(1+(1+kappam.^2).^(-1)).*dA2_0.*dA3_0+a.^(-1).*Rm.^2.*((1+kappam.^2).^(-1)+(-2).*Rm.*(7+6.*(1+kappam.^2).^(-1)).*dS2_0).*dS3_0)+4.*Rm.^3.*(1+2.*(1+kappam.^2).^(-1)).*d3S2_0)+16.*a.^(-1).*Rm.^4.*d3S3_0));
end

if isempty(rho2)
    K2 = [];
else
    dtheta = pi/100;
    thetas = 0:dtheta:2*pi;
    
    fun_to_int = 1./(2.*pi.*mu0).*h_theta(rho2,thetas,equil,amplitudes).^2 ...
        ./sqrt_g(rho2,thetas,equil,amplitudes);
    
    K2 = dtheta.*sum(fun_to_int(:,2:end),2);
end

K = cat(1,K1,K2);

%{
K = zeros(size(rho));

rho(rho==0) = 1e-10;

for i=1:length(rho)
    r = rho(i);
    fun_to_int = @(theta) 1/(2.*pi.*mu0).*grad_rho(r,theta,equil,amplitudes) ...
        ./h_zeta(r,theta,equil,amplitudes).*h_theta(r,theta,equil,amplitudes);
    K(i) = integral(fun_to_int,0,2*pi);
end
%}

end
